#include <stdio.h>

/* No closures: pass function pointers instead. */
typedef int (*pred)(int);
typedef int (*fn)(int);

static int is_even(int x) { return x % 2 == 0; }
static int square(int x)  { return x * x; }

static int filter_map(const int *in, int n, pred p, fn f, int *out) {
    int k = 0;
    for (int i = 0; i < n; i++)
        if (p(in[i])) out[k++] = f(in[i]);
    return k;
}

int main(void) {
    int xs[10], ys[10];
    for (int i = 0; i < 10; i++) xs[i] = i + 1;
    int k = filter_map(xs, 10, is_even, square, ys);
    for (int i = 0; i < k; i++) printf(i ? " %d" : "%d", ys[i]);
    putchar('\n');
    return 0;
}

