#include <stdio.h>

/* A tagged union: C's hand-rolled sum type. */
typedef enum { RECTANGLE, TRIANGLE } Kind;

typedef struct {
    Kind kind;
    union {
        struct { int width, height; } rect;
        struct { int base, height; } tri;
    };
} Shape;

int area(const Shape *s) {
    switch (s->kind) {
    case RECTANGLE: return s->rect.width * s->rect.height;
    case TRIANGLE:  return s->tri.base * s->tri.height / 2;
    }
    return 0;
}

int main(void) {
    Shape r = { .kind = RECTANGLE, .rect = { 3, 4 } };
    Shape t = { .kind = TRIANGLE,  .tri  = { 10, 3 } };
    printf("Rectangle: %d\n", area(&r));
    printf("Triangle: %d\n", area(&t));
    return 0;
}

