/* Classic K&R string copy: the pointer idiom C is famous for. */
void copy(char *dst, const char *src) {
    while ((*dst++ = *src++))
        ;
}

int main(void) {
    char buf[32];
    copy(buf, "pointers!");
    for (char *p = buf; *p; p++)
        printf("%c@%td ", *p, p - buf);
